/*
 * Runtime view of public/sequences/manifest.json (generated by
 * scripts/build-manifest.mjs) — frame counts, dimensions, and byte weights
 * per segment/tier. The manifest, not phases.ts, is the truth for what's
 * actually on disk.
 */

export interface VariantInfo {
  w: number;
  h: number;
  frames: number;
  bytes: number;
}

export interface SegmentInfo {
  fps: number;
  format: "avif" | "webp";
  variants: Record<string, VariantInfo>;
}

export interface Manifest {
  generatedAt: string;
  segments: Record<string, SegmentInfo>;
}

let manifest: Manifest | null = null;
let pending: Promise<Manifest> | null = null;

export function loadManifest(): Promise<Manifest> {
  if (manifest) return Promise.resolve(manifest);
  pending ??= fetch("/sequences/manifest.json")
    .then((r) => {
      if (!r.ok) throw new Error(`manifest fetch ${r.status}`);
      return r.json() as Promise<Manifest>;
    })
    .then((m) => (manifest = m));
  return pending;
}

/** Synchronous access once loaded — hot loops must not await. */
export function getManifest(): Manifest | null {
  return manifest;
}

/** Smallest tier whose width covers the viewport at (capped) DPR. */
export function pickTier(seg: SegmentInfo): string {
  const dpr = Math.min(window.devicePixelRatio || 1, 1.75);
  const need = Math.ceil(window.innerWidth * dpr);
  const tiers = Object.entries(seg.variants).sort((a, b) => a[1].w - b[1].w);
  for (const [name, v] of tiers) if (v.w >= need) return name;
  return tiers[tiers.length - 1][0];
}
